import { Component, computed, input } from '@angular/core';
import { TablerIconComponent, IconStarFilled, IconStarHalfFilled, IconStar } from '@tabler/icons-angular';

/** hrm-rating-cell — số sao đánh giá (chỉ đọc) + giá trị/số lượt tùy chọn. Hỗ trợ nửa sao.
 *  Sao đầy/nửa = vàng (yellow-500); sao rỗng = màu vô hiệu. */
@Component({
  selector: 'hrm-rating-cell',
  imports: [TablerIconComponent],
  template: `
    <span class="rc-stars">
      @for (s of stars(); track $index) {
        <tabler-icon
          class="rc-star"
          [class.rc-on]="s > 0"
          [icon]="s === 2 ? full : s === 1 ? half : empty"
          [size]="starSize()" />
      }
    </span>
    @if (showValue()) { <span class="rc-val">{{ value().toFixed(1) }}</span> }
    @if (count() != null) { <span class="rc-count">({{ count() }})</span> }
  `,
  host: { class: 'hrm-rating-cell' },
  styles: [`
:host { display: inline-flex; align-items: center; gap: 6px; }
.rc-stars { display: inline-flex; align-items: center; gap: 1px; color: var(--text-disabled); }
.rc-star.rc-on { color: var(--yellow-500); }
.rc-val { font-size: var(--fs-13); font-weight: 500; color: var(--text-strong); font-variant-numeric: tabular-nums; }
.rc-count { font-size: var(--fs-12); color: var(--text-sub); }
  `],
})
export class HrmRatingCell {
  readonly value = input(0);
  readonly max = input(5);
  readonly starSize = input(16);
  readonly showValue = input(false);
  /** Số lượt đánh giá; null = ẩn. */
  readonly count = input<number | null>(null);

  protected readonly full = IconStarFilled;
  protected readonly half = IconStarHalfFilled;
  protected readonly empty = IconStar;

  /** Mảng độ đầy mỗi sao: 2=đầy · 1=nửa · 0=rỗng. */
  protected readonly stars = computed(() => {
    const v = this.value();
    return Array.from({ length: this.max() }, (_, i) => (v >= i + 1 ? 2 : v >= i + 0.5 ? 1 : 0));
  });
}
